"""Collision-free symbols for internal and user-visible algebraic constructions."""

from __future__ import annotations

from collections.abc import Mapping

import sympy as sp


def fresh_dummy(prefix: str, **assumptions: object) -> sp.Dummy:
    """Return a scope-local symbol that cannot collide with user symbols."""

    return sp.Dummy(prefix, **assumptions)


def fresh_real_dummy(prefix: str) -> sp.Dummy:
    """Return a collision-free real internal symbol."""

    return fresh_dummy(prefix, real=True)


def _collect_symbols(value: object, out: set[sp.Symbol]) -> None:
    if value is None:
        return
    if isinstance(value, sp.Symbol):
        out.add(value)
        return
    if isinstance(value, sp.Basic):
        out.update(value.free_symbols)
        return
    if isinstance(value, Mapping):
        for key, item in value.items():
            _collect_symbols(key, out)
            _collect_symbols(item, out)
        return
    if isinstance(value, (tuple, list, set, frozenset)):
        for item in value:
            _collect_symbols(item, out)


def collision_free_real_symbols(
    prefix: str,
    count: int,
    *context: object,
    start: int = 0,
) -> tuple[sp.Symbol, ...]:
    """Return readable real symbols whose names do not collide with ``context``.

    These symbols are intended for user-visible coordinates. Internal quantified
    and elimination variables should use :func:`fresh_real_dummy` instead.
    """

    if count < 0:
        raise ValueError("symbol count must be nonnegative")
    symbols: set[sp.Symbol] = set()
    for item in context:
        _collect_symbols(item, symbols)
    used_names = {symbol.name for symbol in symbols}

    result: list[sp.Symbol] = []
    index = start
    while len(result) < count:
        name = f"{prefix}{index}"
        index += 1
        if name in used_names:
            continue
        symbol = sp.Symbol(name, real=True)
        result.append(symbol)
        used_names.add(name)
    return tuple(result)


__all__ = ["collision_free_real_symbols", "fresh_dummy", "fresh_real_dummy"]
